// th15_s3_b1 · TH15 v1.00b Stage 3 Boss1 (nonspell)
// source: st03bs.ecl.txt:50-94 (Boss1), 96-193 (Boss1_at); entry state from Boss():8-48
const TIME_LIMIT: int = 2524;      // 120 opening + 2400 source window + 4 startup allowance
const OPENING_BUFFER: int = 120;

const TH15_BIG_BALL2: int = 656;   // source etSprite(0, 19, 1)
const TH15_PELLET2: int = 368;     // source etSprite(1, 1, 4)

const E_OFFSET_STEP: int = 40503;  // source %E += 3.883222 rad per shot (BAM)

// ---- source Boss() entry movement state: start (0,128), moveLimit(0,128,280,64) ----
// moveRand(60,4,1.0) recipe with this limit: clamp x[-140,140] y[96,160],
// direction inner region = centre +/- width/4, height/4 => x +/-70, y 112..144.

sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

sub card_move_rand() {
    // source 412: signed unit random * pi, then the limit-dependent branches
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
        // central +pi branch is deliberately not normalized before the vertical tests
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

// ---- etOn with aim mode 3 (fixed ring) + etOffsetRad + birth ANIM retreat ----
// spawn = boss + 64 * (cos,sin)(offset) - 4 * velocity  (ANIM a=1 keeps the retreat)
sub fire_ring(shape: int, color: int, n: int, base: int, off: angle, spd: fx) {
    var ox: fx = $self_x + 64fx * cos(off);
    var oy: fx = $self_y + 64fx * sin(off);
    for i in 0..n {
        var a: angle = (base + (i * 65536) / n) as angle;
        _ = fire(shape, color,
                 ox - 4fx * spd * cos(a),
                 oy - 4fx * spd * sin(a),
                 spd, a, none, none);
    }
}

// ---- Boss1_at(A, B): one shot loop; source lines 96-193 ----
sub boss1_at(base: int, b: int, n0: int, n1: int, shots: int, goal: fx, tailwait: int, postwait: int) {
    var eoff: int = rand(65536) - 32768;   // %E = %RANDRAD
    var f2: int = base;                    // %F2 = %A
    var f: int = shots;                    // diffI($F, 50,70,100,150)
    var t: int = 0;                        // source floatTime(1, %C, 200, 0, 1.0, goal)
    // source also stores two unread randoms into F0/F1 each shot; they have no
    // consumer in this closure, so only the draws that reach emitters are kept.
    while f > 0 {
        f = f - 1;
        var c0: fx = 1fx;
        if t < 200 { c0 = 1fx + (goal - 1fx) * (t as fx) / 200fx; }
        fire_ring(TH15_BIG_BALL2, 1, n0, f2, eoff as angle, c0);
        wait(1);
        t = t + 1;
        f2 = f2 + b;
        if n1 > 0 {   // source: unless ($DIFF >= 1) skips the copied emitter
            var c1: fx = 1fx;
            if t < 200 { c1 = 1fx + (goal - 1fx) * (t as fx) / 200fx; }
            var spd: fx = c1 + ((rand(65536) - 32768) as fx / 32768) * 0.1fx;
            fire_ring(TH15_PELLET2, 4, n1, f2, (0 - eoff) as angle, spd);
        }
        f2 = f2 + b;
        eoff = eoff + E_OFFSET_STEP;
        wait(tailwait);
        t = t + tailwait;
    }
    wait(postwait);   // source !N wait(30) after the loop
}

async sub boss_attack() {
    set_invuln(65535);
    set_hitbox(24fx);   // source setHitbox(48,48) -> radius 24
    set_hurtbox(20fx);  // source setHurtbox(40,40) -> radius 20

    var rank: int = global(GVAR_RANK);
    var n0: int = 2;
    var n1: int = 2;
    var b_first: int = -364;     // Easy   : -0.034907 rad = -2deg
    var b_second: int = 364;     // Easy   : +0.034907 rad = +2deg
    var shots: int = 70;
    var tailwait: int = 1;
    var goal: fx = 3fx;
    var postwait: int = 0;
    if rank == RANK_EASY {
        shots = 50; tailwait = 2; n1 = 0;
    } else if rank == RANK_HARD {
        n0 = 3; n1 = 3;
        b_first = -182; b_second = 182;   // -1deg / +1deg
        shots = 100;
    } else if rank == RANK_LUNATIC {
        n0 = 3; n1 = 2;
        b_first = -182; b_second = 1820;  // -1deg / +10deg
        shots = 150; goal = 3.5fx;
    } else {
        b_first = -237; b_second = 237;   // Normal: -1.3deg / +1.3deg
        postwait = 30;
    }

    wait(60);   // source entry wait(60) before the first Boss1_at
    loop {
        boss1_at(32768, b_first, n0, n1, shots, goal, tailwait, postwait);  // A = pi
        wait(20);
        card_move_rand();
        card_wait(60);
        boss1_at(0, b_second, n0, n1, shots, goal, tailwait, postwait);     // A = 0
        wait(20);
        card_move_rand();
        card_wait(60);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 17000, 0, 0, 0, boss_attack);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
